var e=[{id:`aromatics-standard`,group:`knife-and-heat`,title:`Aromatics: from raw to browned`,intro:`Compare the same diced onion at three stages. Look at the centre of each piece, its edges and the pan beneath it.`,scope:`Sweating aims for softened onion without browning. Browned onion is a different useful result when the recipe calls for it; the picture cannot tell you how soft a piece feels.`,image:{src:`standards/aromatics-standard-v1.webp`,thumb:`standards/aromatics-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Raw onion`,description:`Opaque white pieces with firm-looking edges mark the starting point. Even cutting helps the pieces cook at a similar pace.`,image:`Opaque white onion dice in a shallow metal pan.`},{name:`Sweated onion`,description:`Look for a translucent appearance without brown edges. Check a piece for tenderness as well; colour alone does not establish the endpoint.`,image:`Pale, translucent onion dice with a light sheen and no brown edges.`},{name:`Browned onion`,description:`Golden-brown edges and deposits on the pan show a different stage. Choose it for a recipe that wants browned flavour, not as the endpoint of a colourless sweat.`,image:`Golden-brown onion pieces with browned deposits on the pan.`}],links:[{label:`Sweating aromatics`,href:`/technique/sweating-aromatics-soft-never-browned`},{label:`Sweat, sauté and sear`,href:`/lexicon#sweat-vs-saute-vs-sear`},{label:`Practise with pasta e fagioli`,href:`/recipe/pasta-e-fagioli`}],techniques:[`sweating-aromatics-soft-never-browned`],dishes:[],sources:[{title:`Rouxbe: How to Sweat Ingredients`,url:`https://rouxbe.com/cooking-school/how-to-sweat-ingredients`}]},{id:`simmer-standard`,group:`knife-and-heat`,title:`Read the water: poach, simmer, boil`,intro:`Compare a quiet surface with a gentle simmer and a rolling boil. Choose the movement that suits the food and the recipe.`,scope:`These matched pans illustrate different levels of water movement. A still picture cannot measure temperature or show the rhythm of the bubbles; use the linked lesson and observe your own pan.`,image:{src:`standards/simmer-standard-v1.webp`,thumb:`standards/simmer-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Quiet poaching water`,description:`The surface is mostly calm, without vigorous bubbles disturbing it. Gentle treatment is useful for delicate foods; follow their specific cooking method.`,image:`Clear water with a nearly still surface in a metal pan.`},{name:`Gentle simmer`,description:`Small bubbles break the surface with less disturbance than a rolling boil. Watch their frequency and the movement of the liquid, not only the heat setting.`,image:`A few small bubbles breaking the surface of clear water.`},{name:`Rolling boil`,description:`Vigorous bubbles and strong surface movement distinguish this pan. A boil is useful when called for, but it is not interchangeable with a gentle simmer.`,image:`Clear water with vigorous bubbles across its agitated surface.`}],links:[{label:`Holding a bare simmer`,href:`/technique/the-bare-simmer-holding-liquid-below-the-boil`},{label:`Poach, simmer and boil`,href:`/lexicon#poach-simmer-boil`},{label:`Apply gentle heat to poached eggs`,href:`/technique/poaching-eggs`}],techniques:[`the-bare-simmer-holding-liquid-below-the-boil`,`poaching-eggs`],dishes:[],sources:[{title:`Rouxbe: What Is Simmering?`,url:`https://shop.rouxbe.com/tips-techniques/336-what-is-simmering`}]},{id:`pan-sauce-standard`,group:`sauces-and-eggs`,title:`From fond to pan sauce`,intro:`Follow the brown deposits left after cooking into a loosened liquid and a more concentrated sauce.`,scope:`This is a general pan-sauce sequence, not a complete recipe. The ingredients determine the final body; reducing a liquid does not guarantee that it will coat a spoon, and not every sauce needs a butter finish.`,image:{src:`standards/pan-sauce-standard-v1.webp`,thumb:`standards/pan-sauce-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Brown fond`,description:`Brown deposits remain after the cooked food is removed. These flavourful bits are the starting point here; scorched black residue is not the target.`,image:`Brown cooking deposits on the exposed base of a metal pan.`},{name:`Deglaze`,description:`The recipe’s liquid loosens the deposits as they are scraped from the pan. Notice the exposed metal and the colour carried into the liquid.`,image:`A wooden utensil loosening brown deposits into liquid in the same pan.`},{name:`Reduce and check`,description:`The finished sauce appears cohesive, with a small sample in the spoon. Check its consistency and flavour against the recipe before deciding whether it needs further reduction or finishing.`,image:`Glossy brown pan sauce with a spoon holding a small sample.`}],links:[{label:`Deglazing and pan sauces`,href:`/technique/deglazing-and-pan-sauces`},{label:`Reducing a sauce`,href:`/technique/reducing-a-sauce`},{label:`Reduction, nappe and mounting`,href:`/lexicon#reduction-nappe-and-mounting`},{label:`Practise with chicken piccata`,href:`/recipe/chicken-piccata`}],techniques:[`deglazing-and-pan-sauces`,`reducing-a-sauce`],dishes:[],sources:[{title:`Rouxbe: How to Make Pan Sauce`,url:`https://rouxbe.com/cooking-school/how-to-make-pan-sauce`}]},{id:`straining-standard`,group:`sauces-and-eggs`,title:`Straining: what stays, what passes`,intro:`Look at the cooked pieces caught in the mesh, then the liquid collected beneath it.`,scope:`This study shows solids separated from liquid by a fine-mesh sieve. Straining does not automatically make a liquid perfectly clear; pressing, filtering and clarification serve different goals.`,image:{src:`standards/straining-standard-v1.webp`,thumb:`standards/straining-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Solids retained`,description:`The fine mesh catches the larger cooked vegetable pieces while liquid drains into a bowl. Use a stable sieve and a receiving bowl with enough capacity.`,image:`Cooked vegetable pieces retained in a fine-mesh sieve set over a bowl.`},{name:`Liquid collected`,description:`The strained liquid has no visible large vegetable pieces. Follow the recipe on whether to press the solids or let them drain; those choices can change the result.`,image:`A bowl of smooth-looking strained liquid without large vegetable pieces.`}],links:[{label:`Straining and passing through a sieve`,href:`/technique/straining-and-passing-through-a-sieve`},{label:`Sieves, tamis and food mills`,href:`/lexicon#sieves-chinois-tamis-and-food-mill`},{label:`Compare the strained and blended routes in barszcz`,href:`/recipe/barszcz`}],techniques:[`straining-and-passing-through-a-sieve`],dishes:[],sources:[{title:`Rouxbe: Stock Fundamentals, straining and cooling`,url:`https://rouxbe.com/cooking-school/how-to-make-stock-fundamentals`}]},{id:`puree-texture-standard`,group:`sauces-and-eggs`,title:`Potato texture: rustic, smooth, gluey`,intro:`Compare the surface and body of three plain potato preparations. Coarse and smooth can both be intentional; a sticky, gluey result is a different observation.`,scope:`These are plain potato preparations. The third illustrates a gluey texture that overworking can produce; appearance alone cannot prove how it happened. Choose a coarse or smooth finish to suit the recipe.`,image:{src:`standards/puree-texture-standard-v1.webp`,thumb:`standards/puree-texture-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Rustic mash`,description:`Small pieces and an uneven surface remain. This can be a deliberate style when the potato is tender; visible pieces alone do not prove it is undercooked.`,image:`A pale mound of roughly mashed potato with visible small pieces.`},{name:`Smooth finish`,description:`A ricer is one way to make evenly textured potato before gently incorporating the recipe’s additions. Look for the smooth result; the picture cannot identify the tool used.`,image:`A pale, evenly textured potato mound with soft smooth folds.`},{name:`Gluey texture`,description:`The sticky appearance and short stretch at the spoon contrast with the first two finishes. Excessive mixing can make potato gluey; stop mixing once the recipe’s desired texture is reached.`,image:`A glossy, sticky-looking potato mixture clinging in a short stretch to a spoon.`}],links:[{label:`Mashing and puréeing`,href:`/technique/mashing-and-pureeing`},{label:`Sieves, tamis and food mills`,href:`/lexicon#sieves-chinois-tamis-and-food-mill`},{label:`Practise a potato mash with champ`,href:`/recipe/champ`}],techniques:[`mashing-and-pureeing`],dishes:[],sources:[{title:`Idaho Potato Commission: texture, ricing and overmixing`,url:`https://idahopotato.com/dr-potato/print/my-potato-has-large-lumps-in-it-and-after-baking-and-mashing-it-the-lumps-are-not-going-away-what-is-this`}]}],t=[.02,.34,.66].map(e=>({x:e,y:.05,width:.32,height:.88})),n=[0,1].flatMap(e=>[0,1,2].map(t=>({x:.025+t*.315,y:e===0?.09:.505,width:.315,height:e===0?.4:.37}))),r=e=>({src:`standards/${e}-study-v1.webp`,thumb:`standards/${e}-study-v1.thumb.webp`,width:1536,height:1024}),i=[{id:`brown-butter-study`,group:`cooks-eye`,title:`Brown butter: read the milk solids`,intro:`Follow the particles in the pan and spoon. The pale pan makes the change easier to see.`,scope:`An illustrated comparison, not a timer or a house recipe. The third view is a scorched batch, not a desired next stage. Check aroma and the intended recipe as well as appearance.`,image:r(`brown-butter`),focus:t,subjects:[{name:`Melting and foaming`,description:`Pale foam covers much of the yellow liquid. The milk solids have not yet developed the toasted colour shown in the middle view.`,image:`Pale foamy butter in an ivory pan, with a pale spoon sample.`},{name:`Toasted milk solids`,description:`Golden-brown particles stand out against the clear butterfat. Watch the solids closely; the pan remains hot after it leaves the heat.`,image:`Golden butterfat with brown particles, repeated in the spoon below.`},{name:`Scorched solids`,description:`Very dark particles mark a burnt comparison. Straining out the particles does not reliably remove the bitter flavour; make a fresh batch.`,image:`Near-black particles in darkened butter, with a matching spoon sample.`}],learning:{observe:`Compare the particles, not only the overall colour of the liquid.`,explain:`Browning milk solids creates toasted flavour. Brown butter is different from clarified butter, from which solids have been removed.`,apply:`Use Swordfish Grenobloise to connect the technique with its brown butter, lemon and capers. Confirm the current finish with the kitchen.`,question:`Which view suits a brown-butter finish, and what would you check beyond colour?`,answer:`View 2 illustrates toasted solids. Check the aroma and the recipe’s intended stage, and account for continuing heat. View 3 is a failure comparison.`},links:[{label:`Brown-butter technique`,href:`/technique/brown-butter`}],techniques:[`brown-butter`],dishes:[`d-jgihqqda`,`d-5p5b1hjn`],sources:[{title:`King Arthur Baking: how to brown butter`,url:`https://www.kingarthurbaking.com/blog/2020/01/08/brown-butter`}]},{id:`custard-structures`,group:`cooks-eye`,title:`Custards: pouring, piping and setting`,intro:`Three separate preparations show how a cream can flow, hold a ridge or retain a smooth scoop.`,scope:`These are different formulas, not successive stages of one custard. The chocolate example is a general chilled crémeux; it does not specify Brennan’s recipe, gelatin content or plating. Appearance cannot establish safe preparation.`,image:r(`custard-structures`),focus:t,subjects:[{name:`Crème anglaise`,description:`A pouring custard coats the spoon and flows back into the bowl. A starch-free stirred custard needs gentle, recipe-specific heating.`,image:`Pale vanilla cream flowing from a spoon into a bowl.`},{name:`Crème pâtissière`,description:`Pastry cream holds visible piped ridges. Its starch changes both structure and cooking method; follow its formula rather than a blanket rule against boiling custards.`,image:`Thick pale pastry cream in piped ridges, with a small piped sample below.`},{name:`Chilled chocolate crémeux`,description:`This dense, smooth example retains a scoop. A chocolate crémeux may combine a custard base with chocolate; its chilled structure depends on the formula.`,image:`A smooth dark chocolate cream with a scooped hollow and a dense spoonful.`}],learning:{observe:`Look for flow, a held ridge and a retained scoop. The examples should not all have the same consistency.`,explain:`Egg, starch, chocolate and chilling contribute differently. Tempering is a mixing step, not a universal final temperature.`,apply:`Describe Chocolate Crémeux as smooth and creamy, then use the saved dish ingredients to explain its crumble, oil and salt. Do not infer allergens from the image.`,question:`Why would “never boil any custard” be misleading?`,answer:`A starch-free pouring custard and a starch-thickened pastry cream need different treatment. Use the specific formula and its verified process, not a single rule for every cream.`},links:[{label:`Tempering a custard`,href:`/technique/tempering-a-custard`},{label:`Pastry-cream lesson`,href:`/cuisine?ch=pastry&e=creme-patissiere`}],techniques:[`tempering-a-custard`],dishes:[`d-kgmv4fmp`],sources:[{title:`King Arthur Baking: pastry cream`,url:`https://www.kingarthurbaking.com/recipes/pastry-cream-creme-patissiere-recipe`},{title:`Valrhona: chocolate crémeux and its structure`,url:`https://www.valrhona.com/en/l-ecole-valrhona/discover-l-ecole-valrhona/chocolate-terminology/chocolate-cremeux/be-inspired`}]},{id:`meringue-peaks`,group:`cooks-eye`,title:`Meringue: choose the intended peak`,intro:`Compare the drooping peak, bent tip and upright tip in matched bowls and whisk samples.`,scope:`These views compare texture. They do not identify French, Swiss or Italian preparation, pasteurisation or a safe-to-eat state. Stiffer is not always better; use the peak called for by the recipe.`,image:r(`meringue-peaks`),focus:t,subjects:[{name:`Soft peak`,description:`The peak bends over readily and settles into the foam. Check with the whisk rather than judging only the shiny surface.`,image:`A low drooping mound of white foam with a softly falling whisk sample.`},{name:`Medium peak`,description:`The body holds more shape while the tip bends. Peak names vary between recipes; match the recipe’s described behaviour.`,image:`A taller white peak with a visibly curved tip.`},{name:`Stiff peak`,description:`The lifted tip stands upright. This useful endpoint for some recipes is different from dry, clumpy overbeaten foam.`,image:`A firm tall upright white peak with a matching whisk sample.`}],learning:{observe:`Compare the tip and the body beneath it, then check the actual mixture with a whisk.`,explain:`Whipping changes the foam’s ability to hold shape. A glossy surface alone cannot tell you the required endpoint.`,apply:`Connect Lemon Tart with its meringue component. Learn the texture here, then confirm the kitchen’s preparation and finish.`,question:`Your recipe asks for soft peaks. Should you keep whipping until view 3?`,answer:`No. View 1 is the intended comparison. More stiffness is a different result, not an automatic improvement.`},links:[{label:`Whipping a meringue`,href:`/technique/whipping-a-meringue`},{label:`Meringue methods`,href:`/cuisine?ch=pastry&e=meringues`}],techniques:[`whipping-a-meringue`],dishes:[`d-lfwbmoys`],sources:[{title:`King Arthur Baking: meringue rules`,url:`https://www.kingarthurbaking.com/blog/2018/05/17/meringue-rules`}]},{id:`puff-pastry-layers`,group:`cooks-eye`,title:`Puff pastry: read the layers`,intro:`Look at the cut edge: a raw laminate, open baked layers and a closer layered structure.`,scope:`Layer thickness is enlarged for clarity; this is not a scale drawing or a fold-count specification. The lower third sample is a structural comparison, not proof of one baking fault. This is unyeasted puff pastry, not croissant dough.`,image:r(`puff-pastry`),focus:t,subjects:[{name:`Raw laminate`,description:`Dough and butter form distinct thin layers. Keep them separate through the recipe’s rolling, folding and chilling method.`,image:`An enlarged pale raw pastry edge with fine alternating strata.`},{name:`Open baked layers`,description:`Steam helps separate the layers during baking. The cut face shows delicate leaves and open spaces, rather than a bread-like crumb.`,image:`A tall golden pastry with many thin lifted leaves and open spaces.`},{name:`Closer baked layers`,description:`The leaves sit closer together and the piece is lower. The picture alone cannot explain the cause or whether that texture suits a particular recipe.`,image:`A lower golden pastry piece with closer layers visible at the cut edge.`}],learning:{observe:`Use the cut edge, not only the glossy top, to describe the structure.`,explain:`Lamination separates dough with fat; water turning to steam helps lift the layers. Fold schedules and desired rise vary.`,apply:`Lamb Shank en Croûte combines tender lamb with pastry. Describe that contrast without assuming the house’s pastry supplier, fold count or assembly method.`,question:`Does a lower puff-pastry sample prove the oven was too cold?`,answer:`No. It is an observation, not a diagnosis. Review the formula, handling, intended shape and baking process before deciding why it rose differently.`},links:[{label:`Lamination technique`,href:`/technique/lamination`}],techniques:[`lamination`],dishes:[`d-00p5tuen`],sources:[{title:`King Arthur Baking: puff pastry at the bakery`,url:`https://www.kingarthurbaking.com/blog/2013/08/02/puff-pastry-layer-it-like-the-pros`}]},{id:`braise-confit-render`,group:`cooks-eye`,title:`Braise, confit and render: three different jobs`,intro:`Compare the cooking medium and the job it does. These are three separate methods, not a sequence.`,scope:`General method illustrations, not Brennan’s production instructions. Liquid depth, heat, time and the final texture depend on the recipe. A still cannot demonstrate tenderness, safe cooking, cooling or storage.`,image:r(`braise-confit-render`),focus:t,subjects:[{name:`Braising in liquid`,description:`Browned meat sits partly in a stock-based liquid in this example. Gentle moist cooking can tenderise a tougher cut; check the actual meat for the recipe’s intended texture.`,image:`Browned short-rib pieces partly submerged in brown liquid with vegetables.`},{name:`Duck confit in fat`,description:`The duck legs are covered by clear melted fat. Traditional duck confit uses seasoned or cured legs cooked gently in fat; crisping the skin is a separate finishing choice.`,image:`Two duck legs visible below a continuous clear golden fat surface.`},{name:`Rendering fat`,description:`Heating fatty tissue releases liquid fat. The small browned skin pieces are cracklings; rendering produces a cooking fat rather than a braised meat sauce.`,image:`Small curled golden skin pieces surrounded by clear released fat.`}],learning:{observe:`Compare stock-based liquid, covering fat and fat released from small trimmings.`,explain:`Braising tenderises in a moist environment; confit cooks gently in fat; rendering releases fat from tissue.`,apply:`Relate braising to Eggs Owen and fall lamb, and confit to Duck Confit Waffle. Learn the distinction without treating these examples as house formulas.`,question:`Can the picture or a fixed cooking time prove that a braise is ready?`,answer:`No. Check tenderness, measured cooking requirements and the intended finish. An intact portion and pulled meat can both be correct for different recipes.`},links:[{label:`Braising`,href:`/technique/braising`},{label:`Confit`,href:`/technique/confit`},{label:`Rendering fat`,href:`/technique/rendering-fat-and-cooking-in-what-runs-out`}],techniques:[`braising`,`confit`,`rendering-fat-and-cooking-in-what-runs-out`],dishes:[`d-44jfmkdb`,`d-00p5tuen`,`d-vbtv3rru`],sources:[{title:`Rouxbe: braising and combination cooking`,url:`https://rouxbe.com/cooking-school/braising-combination-cooking`},{title:`Culinary Institute of America: A Taste of France, duck confit and rendering, page 56`,url:`https://www.ciaconsulting.org/wp-content/uploads/2025/03/CIP-A-Taste-of-France-Course-Guide-v210-CP.pdf`}]},{id:`agnolotti-shaping`,group:`cooks-eye`,title:`Agnolotti del plin: fold, pinch and seal`,intro:`Follow the filled sheet into compact pinched pockets, then examine the wrapper and filling in section.`,scope:`An illustrative general shaping sequence. Dough thickness, quantities, filling, size and cooking method are recipe-specific. The brown-green filling is a visual example, not an ingredient specification or Brennan’s approved shape.`,image:r(`agnolotti-shaping`),focus:n,subjects:[{name:`Place the filling`,description:`Spaced small mounds leave clean dough available for the fold and seals. Follow the recipe’s amount and spacing.`,image:`Three filling mounds spaced along one side of a pasta sheet.`},{name:`Fold and close`,description:`Fold the sheet over the filling and close the long edge. Avoid trapping air or filling in the seam.`,image:`A folded strip covering three mounds with a clean long margin.`},{name:`Pinch between pockets`,description:`Pinching between the mounds creates the defining constrictions. Preserve sealed dough between adjacent portions.`,image:`Connected filled pockets separated by upright pinched divisions.`},{name:`Separate the plin`,description:`Cut through the sealed areas to separate the pockets. The pinched ends should remain closed.`,image:`Three separate compact folded pockets with upright pinched ends.`},{name:`Inspect a seam`,description:`Look for a closed end and a compact folded form. An intact appearance still needs a careful hands-on seal check.`,image:`An enlarged folded pouch showing its narrow lip and pinched ends.`},{name:`Read the section`,description:`The cut example separates the thin wrapper from the filling. Learn the structure without inferring exact ingredients from its colour.`,image:`Two cut halves showing a thin pasta wrapper around fine brown-green filling.`}],learning:{observe:`Follow the upright pinches from the joined row into the separated pockets.`,explain:`Plin refers to the pinch. The filled sheet is folded and pinched before the individual pockets are separated.`,apply:`For Brennan’s fall Agnolotti del Plin, use the saved ingredient list to explain pork, collards, ricotta, Parmesan and lemon pangrattato. This study explains the pasta form.`,question:`Which view creates the divisions that must stay sealed when the pasta is cut?`,answer:`View 3. The pinched dough divides the filling into pockets; the cuts in view 4 must preserve those seals.`},links:[{label:`Fresh pasta`,href:`/technique/fresh-pasta`},{label:`Fresh-pasta lesson`,href:`/cuisine?ch=larder&e=fresh-pasta`}],techniques:[`fresh-pasta`],dishes:[`d-u34mwyw8`],sources:[{title:`Eataly: agnolotti del plin shaping method`,url:`https://www.eataly.com/us_en/magazine/recipes/pasta-recipes/agnolotti-del-plin`}]}],a=`h-g02pdomw`,o=[{id:`cooks-eye`,title:`The Cook’s Eye: heat, texture and structure`,intro:`Six studies for your next practice: look closely, explain the change, then connect it to a Brennan’s dish.`},{id:`ingredients`,title:`Ingredients at a glance`,intro:`Explore herbs, the Louisiana larder and the seafood and parcel ingredients on Brennan’s menu.`},{id:`knife-and-heat`,title:`Knife work and heat`,intro:`Look for even cuts, the direction of the grain, onion colour and the movement of water in the pan.`},{id:`sauces-and-eggs`,title:`Sauces, eggs and texture`,intro:`Follow fond, emulsions and texture from the pan to the spoon, then recognise the parts of Eggs Hussarde.`}],s=[{id:`brennans-sauces`,group:`sauces-and-eggs`,title:`Six sauces, seen side by side`,intro:`Compare colour, body and the ingredients that distinguish six sauces named in the Brennan’s study pack.`,scope:`These are classic sauce studies, not photographs of the restaurant’s current service. Recipes and colour vary; the plain beurre blanc shown here does not specify the house’s preserved-lemon version.`,image:{src:`house/brennans/brennans-sauces-v1.webp`,thumb:`house/brennans/brennans-sauces-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`Hollandaise`,description:`A smooth, buttery egg-yolk emulsion with lemon. Look for a pale yellow body that coats the spoon.`,image:`Pale butter-yellow sauce coating a spoon in a white saucer.`},{name:`Béarnaise`,description:`A rich butter sauce distinguished by its tarragon. The chopped herbs remain visible in the sauce.`,image:`Yellow sauce flecked with green herbs, coating a spoon.`},{name:`Choron`,description:`Béarnaise with tomato: the tomato changes the colour while the herbal character remains.`,image:`Soft coral sauce with green herb flecks.`},{name:`Foyot`,description:`Béarnaise enriched with reduced beef glaze. Compare its tan colour with Choron’s tomato tint.`,image:`Light caramel-tan sauce with green herb flecks.`},{name:`Marchand de vin`,description:`A savoury red-wine brown sauce, illustrated here with mushrooms and shallot. Compare it with the pale butter sauces; confirm the current house ingredients with the chef.`,image:`Glossy red-brown sauce with chopped mushroom and shallot.`},{name:`Beurre blanc`,description:`A white-wine and butter emulsion. It should look creamy and cohesive, rather than like separated oil.`,image:`Smooth ivory sauce spreading in a white saucer.`}],links:[{label:`Hollandaise technique`,href:`/technique/hollandaise`},{label:`Béarnaise recipe`,href:`/recipe/sauce-bearnaise`},{label:`The cold-butter mount`,href:`/recipe/beurre-blanc-the-cold-butter-mount`}],techniques:[],dishes:[`d-1q0xk7jv`,`d-fs311zha`,`d-44jfmkdb`,`d-4jee8o34`,`d-5wcuejdy`,`d-s1bqzuks`]},{id:`poached-egg-standard`,group:`sauces-and-eggs`,title:`A poached egg: the result and the faults`,intro:`Read the water’s surface, then compare the shape of the white and the texture of the cut yolk.`,scope:`The fault panel brings two different problems together. Violent bubbles can disrupt the white; a firm yolk reflects cooking time and heat, not a rolling boil alone. Use the technique lesson alongside the picture.`,image:{src:`standards/poached-egg-standard-v1.webp`,thumb:`standards/poached-egg-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Gentle poaching`,description:`The water barely shivers. The drained white holds together, and the cut egg illustrates a flowing yolk.`,image:`A quiet pan above compact poached eggs, including one cut open with a flowing yolk.`},{name:`Disrupted white and a firm yolk`,description:`The rolling water illustrates rough treatment of the delicate white. The ragged white and set yolk are separate observations to check.`,image:`A vigorously bubbling pan above a ragged egg and another cut open with a firm yolk.`}],links:[{label:`Poaching eggs`,href:`/technique/poaching-eggs`},{label:`Poach, simmer and boil`,href:`/lexicon#poach-simmer-boil`}],techniques:[`poaching-eggs`],dishes:[`d-1q0xk7jv`,`d-fs311zha`]},{id:`louisiana-larder`,group:`ingredients`,title:`The Louisiana larder`,intro:`Recognise the trinity, two smokehouse ingredients and the shape of okra.`,scope:`The first three subjects form the Louisiana trinity: onion, celery and green bell pepper. This is an ingredient study; it does not establish every ingredient in a restaurant dish.`,image:{src:`plates/louisiana-larder-v1.webp`,thumb:`plates/louisiana-larder-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`Onion`,description:`One of the trinity’s three vegetables. Compare the whole bulb with the diced flesh.`,image:`A golden-skinned onion beside a small pile of white dice.`},{name:`Celery`,description:`The ribbed green stalk supplies the second part of the trinity.`,image:`Pale green celery ribs and leaves beside small dice.`},{name:`Green bell pepper`,description:`Green bell pepper completes this trinity. Carrot belongs to the familiar French mirepoix instead.`,image:`A glossy green bell pepper beside chopped green pieces.`},{name:`Cajun andouille`,description:`A coarse pork sausage with a pronounced smoked character. The cut face helps distinguish it from a fine, smooth sausage.`,image:`A dark smoked sausage with thick slices showing coarse meat and fat.`},{name:`Tasso`,description:`Heavily seasoned, smoked pork shoulder used in small pieces as a flavouring ingredient; it is not a whole ham.`,image:`A spice-crusted slab of smoked pork, a cut pink face and small cubes.`},{name:`Okra`,description:`Compare the ridged pod with its cut, seeded cross-section.`,image:`Green okra pods and cut rounds with pale seeds.`}],links:[{label:`Tasso and Cajun andouille`,href:`/lexicon#tasso-and-cajun-andouille`},{label:`Chicken and andouille gumbo`,href:`/recipe/chicken-and-andouille-gumbo`}],techniques:[],dishes:[`d-r3h9vj7a`,`d-bqznncn6`,`d-1gj8ji36`]},{id:`roux-colour-ladder`,group:`sauces-and-eggs`,title:`Roux: from pale to dark`,intro:`Compare an evenly cooked roux at five colour stages with a scorched batch.`,scope:`Stop at the stage the recipe calls for. Darker roux develops a deeper toasted flavour and has less thickening power. The numbered stages are a visual comparison, not a cooking timer.`,image:{src:`standards/roux-colour-ladder-v1.webp`,thumb:`standards/roux-colour-ladder-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`White`,description:`Pale and evenly mixed, with no dry pockets. A pale roux is used for sauces such as béchamel.`,image:`A smooth pale cream roux in a metal pan.`},{name:`Blond`,description:`A light golden stage, used for sauces such as velouté.`,image:`An even straw-gold roux.`},{name:`Peanut-butter brown`,description:`An intermediate brown: keep stirring and judge against the recipe’s intended stage.`,image:`An evenly coloured light-brown roux.`},{name:`Milk-chocolate brown`,description:`An even, deeper brown, the target named by the Table’s chicken and andouille gumbo recipe.`,image:`Glossy milk-chocolate-brown roux.`},{name:`Brick`,description:`A deep red-brown stage. Even colour matters; dark roux should not contain scorched black flecks.`,image:`A deep red-brown roux without black specks.`},{name:`Scorched`,description:`Black flecks signal a burnt batch. Start again; stirring the flecks back in does not remove their bitterness.`,image:`Dark roux with black flecks and a burnt ring around the pan.`}],links:[{label:`Making a roux`,href:`/technique/making-a-roux`},{label:`Roux, slurry and liaison`,href:`/lexicon#roux-slurry-and-liaison`}],techniques:[`making-a-roux`],dishes:[`d-r3h9vj7a`]},{id:`hollandaise-standard`,group:`sauces-and-eggs`,title:`Hollandaise: build, recognise, recover`,intro:`Follow the yolk foam into an emulsion, then distinguish a smooth sauce from curdling and separation.`,scope:`Use the linked recipe for the method. The last panel illustrates the fresh-base rescue for a separated sauce; it does not show cooked egg curds turning back into uncooked yolk.`,image:{src:`standards/hollandaise-standard-v1.webp`,thumb:`standards/hollandaise-standard-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`Whisk the sabayon`,description:`The yolk mixture becomes pale and airy, leaving a ribbon briefly on the surface. The bowl sits clear of the water beneath it.`,image:`A lifted whisk trailing a ribbon of pale yolk foam over a water bath.`},{name:`Add butter gradually`,description:`Work warm clarified butter into the yolks in a fine stream. Each addition should disappear into the sauce.`,image:`A thin thread of golden butter entering a bowl beside a whisk.`},{name:`A stable sauce`,description:`Look for a smooth, glossy body that coats the whisk, without a separate oily slick.`,image:`Pale yellow sauce falling from the whisk in a thick smooth ribbon.`},{name:`Too hot`,description:`Graininess and cooked yolk lumps are different from a smooth emulsion.`,image:`Grainy yellow sauce with small curdled lumps.`},{name:`Separated`,description:`Free butter over thin liquid signals a broken emulsion. Temperature and the pace of adding fat both matter.`,image:`Clear yellow butter pooling over a thin pale liquid.`},{name:`A fresh base`,description:`The recipe’s rescue starts with a fresh yolk in a clean bowl, then works the separated sauce into it gradually.`,image:`Separated sauce being whisked slowly into a fresh yolk in a clean bowl.`}],links:[{label:`Hollandaise and the two ways it splits`,href:`/recipe/hollandaise-and-the-two-ways-it-splits`},{label:`Building an emulsion`,href:`/technique/building-an-emulsion`}],techniques:[`hollandaise`,`building-an-emulsion`],dishes:[`d-1q0xk7jv`,`d-44jfmkdb`]},{id:`french-herbs`,group:`ingredients`,title:`The French herbs`,intro:`Compare the tender fines herbes quartet with the smaller, tougher leaves of thyme and rosemary.`,scope:`Parsley, chervil, chives and tarragon form the classic fines herbes quartet. Thyme and rosemary are shown for contrast, not as part of that blend. This is a kitchen comparison of known culinary herbs, not a wild-plant identification guide; confirm the house’s current herb mix at lineup.`,image:{src:`plates/french-herbs-v1.webp`,thumb:`plates/french-herbs-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`Flat-leaf parsley`,description:`Look for broad, flat, toothed leaflets. Its fresh green flavour is the familiar starting point for the tender-herb comparison.`,image:`Bright green, broad, toothed leaflets on slender stems.`},{name:`Chervil`,description:`The softer, finely divided leaves look lacy beside parsley. Its delicate anise note is best appreciated in fresh finishing herbs.`,image:`Fine, feathery, pale green leaves on delicate branching stems.`},{name:`Chives`,description:`The narrow leaves are round and hollow, with a mild onion flavour. These are common chives, rather than the flat leaves of garlic chives.`,image:`Slender tubular green leaves beside pale purple, rounded flower heads.`},{name:`French tarragon`,description:`Long, narrow, smooth leaves accompany a pronounced anise-like aroma. Tarragon is the distinctive herb in the béarnaise family of sauces.`,image:`Long, narrow, pointed leaves along upright green stems.`},{name:`Thyme`,description:`Tiny leaves cluster on short woody sprigs. Compare this compact, sturdier structure with the four tender herbs above.`,image:`Short woody sprigs bearing many tiny oval grey-green leaves.`},{name:`Rosemary`,description:`Firm, needle-like leaves grow along woody stems. Its resinous aroma is stronger than the soft green character of parsley.`,image:`Woody sprigs with narrow dark green leaves and paler undersides.`}],links:[{label:`Flat-leaf parsley`,href:`/lexicon#flat-leaf-parsley`},{label:`Chervil`,href:`/lexicon#chervil`},{label:`Chives`,href:`/lexicon#chives`},{label:`Tarragon`,href:`/lexicon#tarragon`},{label:`Thyme`,href:`/lexicon#thyme`},{label:`Rosemary`,href:`/lexicon#rosemary`},{label:`Bright and resinous herb profiles`,href:`/lexicon#herb-profiles-bright-vs-resinous`}],techniques:[],dishes:[`d-5p5b1hjn`,`d-nd0d2czb`,`d-fs311zha`,`d-4jee8o34`,`d-5wcuejdy`],sources:[{title:`Royal Horticultural Society: culinary herbs`,url:`https://www.rhs.org.uk/herbs/growing`},{title:`RHS: common and garlic chives`,url:`https://www.rhs.org.uk/herbs/chives/grow-your-own`},{title:`University of Nevada, Reno: culinary herbs and blends`,url:`https://extension.unr.edu/publication.aspx?PubID=2755`}]},{id:`searing-standard`,group:`knife-and-heat`,title:`Searing: crust and interior`,intro:`Read two separate things: the browning on the surface and the band of cooked meat beneath it.`,scope:`The wet pan and grey band illustrate different observations, not a single proven cause. Surface moisture, crowding, heat, time and steak thickness all matter. The pink interior is an illustration, not a temperature reading or a house doneness specification.`,image:{src:`standards/searing-standard-v1.webp`,thumb:`standards/searing-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Developed crust`,description:`Compare the even brown surface with the narrow cooked band in the cut view. Browning builds flavour; it does not seal juices inside the meat.`,image:`A steak with an even mahogany-brown face in a pan, above a cut view with a thin brown edge and pink centre.`},{name:`Wet surface and a wider grey band`,description:`Liquid surrounds the patchily browned steak. Below it, a broader grey band shows a less even interior. Check the cooking method; the picture alone cannot tell you which factor caused it.`,image:`A wet, patchily browned steak in a crowded pan, above a cut view with a broad grey band around a smaller pink centre.`}],links:[{label:`Searing: the hard crust`,href:`/technique/searing-the-hard-crust`},{label:`Searing and pan technique`,href:`/lexicon#searing-and-pan-technique`},{label:`Reverse sear and the grey band`,href:`/lexicon#reverse-sear-and-the-gray-band`}],techniques:[`searing-the-hard-crust`],dishes:[],sources:[{title:`Rouxbe: searing and the seal-in-juices myth`,url:`https://shop.rouxbe.com/cooking-school/searing`}]},{id:`resting-slicing-standard`,group:`knife-and-heat`,title:`Resting and slicing across the grain`,intro:`Find the direction of the muscle fibres, then compare a cross-cut slice with a strip cut along them.`,scope:`Resting and slicing direction are separate decisions. Resting can reduce liquid lost when meat is cut, but a pool on the board alone cannot establish how long it rested. The hanger steak is a general technique example, not Brennan’s plating or doneness standard.`,image:{src:`standards/resting-slicing-standard-v1.webp`,thumb:`standards/resting-slicing-standard-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`Across the grain`,description:`Locate the long, parallel fibres before slicing across them. Shortening those fibres makes a coarse-grained cut easier to chew. The small amount of board liquid is illustrative, not a pass-or-fail test.`,image:`A cooked hanger steak cut across its grain into short slices on a board with a faint sheen of liquid.`},{name:`Along the grain`,description:`These strips keep long fibres running along their length. The larger pool is a prompt to review resting and cooking, rather than proof that the steak was sliced too soon.`,image:`Long strips with visible parallel muscle fibres beside a larger pool of meat juices.`}],links:[{label:`Resting meat and slicing against the grain`,href:`/technique/resting-meat-and-slicing-against-the-grain`},{label:`Resting, carryover and the thermometer`,href:`/lexicon#resting-carryover-and-the-thermometer`},{label:`Flank, skirt and hanger`,href:`/lexicon#flank-skirt-and-hanger`}],techniques:[`resting-meat-and-slicing-against-the-grain`],dishes:[`d-4jee8o34`,`d-ono6zqmz`],sources:[{title:`Institute of Culinary Education: finding the grain`,url:`https://www.ice.edu/blog/how-find-grain-and-slice-steak-chef`}]},{id:`knife-cuts`,group:`knife-and-heat`,title:`The classical knife cuts`,intro:`Compare cubes, square-sided sticks and leaf ribbons. Even pieces within a cut are the useful habit to practise.`,scope:`Dimensions below follow the Table’s existing lesson; conventions and stick lengths vary between schools and kitchens. The illustration compares shapes and relative sizes, not actual millimetres on your screen. Use a ruler for practice and follow the recipe’s required cut.`,image:{src:`plates/knife-cuts-v1.webp`,thumb:`plates/knife-cuts-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`Brunoise`,description:`Small, even cubes: about 3 × 3 × 3 mm in this lesson. Cut julienne crosswise to make matching dice.`,image:`A neat pile of tiny carrot cubes, the smallest cubes in the study.`},{name:`Small dice`,description:`About 6 × 6 × 6 mm. Each edge is roughly twice the brunoise edge; compare the pieces within the pile for consistency.`,image:`Even carrot cubes with edges about twice those of the brunoise.`},{name:`Medium dice`,description:`About 12 × 12 × 12 mm. These larger cubes still need straight, even faces and closely matching dimensions.`,image:`Larger carrot cubes, with edges about twice those of the small dice.`},{name:`Julienne`,description:`Slender square-sided sticks, about 3 × 3 mm and 5 cm long here. Aim for the same width and thickness throughout.`,image:`A bundle of thin, evenly cut carrot matchsticks.`},{name:`Batonnet`,description:`Thicker square-sided sticks, about 6 × 6 mm and 6 cm long here. Cutting them crosswise at the same interval produces small dice.`,image:`A stack of thicker carrot sticks, slightly longer than the julienne.`},{name:`Chiffonade`,description:`Stack and roll tender leaves, then slice across the roll into ribbons. Keep the cut clean rather than crushing the leaves.`,image:`Fine green basil ribbons beside a rolled bundle of basil leaves.`}],links:[{label:`Knife cuts: dice, julienne, bias`,href:`/technique/knife-cuts-dice-julienne-bias`},{label:`The classical knife-cut ladder`,href:`/lexicon#knife-cuts-the-classical-ladder`}],techniques:[`knife-cuts-dice-julienne-bias`],dishes:[],sources:[{title:`Rouxbe: knife-cut shapes and dimensions`,url:`https://rouxbe.com/tips-techniques/495-types-of-knife-cuts`}]},{id:`eggs-hussarde-components`,group:`sauces-and-eggs`,title:`Eggs Hussarde: five parts to recognise`,intro:`Explore the five named components of Eggs Hussarde, from the English muffin to its two distinct sauces.`,scope:`The numbers identify components, not an assembly sequence. These separate ingredient studies do not establish the restaurant’s portion size, stacking, sauce placement or current china. Confirm those details at the pass.`,image:{src:`house/brennans/eggs-hussarde-components-v1.webp`,thumb:`house/brennans/eggs-hussarde-components-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`English muffin`,description:`Brennan’s menu names a housemade English muffin. Recognise the split bread and open crumb before considering how the kitchen assembles the dish.`,image:`A split English muffin with a lightly toasted, open crumb in the upper-left study.`},{name:`Coffee-cured Canadian bacon`,description:`The menu specifies coffee-cured Canadian bacon. This is a loin cut, distinct from the streaky belly bacon used in many other breakfasts.`,image:`Round slices of pink Canadian bacon with a darker cured edge in the upper-right study.`},{name:`Poached egg`,description:`Poached eggs are named on the Hussarde. The whole and opened views compare white and yolk texture, not a portion count. Eggs Owen uses a soft-boiled egg instead.`,image:`A whole poached egg beside an opened egg with a flowing yolk in the wide centre study.`},{name:`Hollandaise`,description:`This smooth butter-and-yolk emulsion is the pale sauce on the menu. Compare its body and colour with the darker marchand de vin beside it.`,image:`Smooth pale yellow hollandaise in a small white sauce vessel at lower left.`},{name:`Marchand de vin`,description:`The second sauce has a savoury red-wine character. The illustration includes mushrooms and shallot as a sauce study; confirm the current house aromatics and additions with the chef.`,image:`Glossy red-brown marchand de vin with small mushroom and shallot pieces at lower right.`}],links:[{label:`Poaching eggs`,href:`/technique/poaching-eggs`},{label:`Hollandaise technique`,href:`/technique/hollandaise`}],techniques:[],dishes:[`d-1q0xk7jv`],sources:[{title:`Brennan’s: current breakfast and lunch menu`,url:`https://www.brennansneworleans.com/menus/breakfast-and-lunch/`}]},{id:`chateaubriand-study`,group:`knife-and-heat`,title:`Chateaubriand: centre cut to service`,intro:`Locate the centre of the tenderloin, then recognise the roast, summer squash and sauce Foyot named on the dinner menu.`,scope:`This is a cut and component study. The serving arrangement, three illustrated slices and interior colour are illustrative, not Brennan’s portion, plating or doneness standard. Colour alone does not measure temperature; confirm carving and service at the pass.`,image:{src:`house/brennans/chateaubriand-study-v1.webp`,thumb:`house/brennans/chateaubriand-study-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`The centre of the tenderloin`,description:`The thicker head, even centre and tapered tail are separated to make the cut easy to read. The centre provides the thick roast commonly called chateaubriand.`,image:`A trimmed raw tenderloin separated into a thicker head, an even centre roast and a tapered tail.`},{name:`The menu’s three components`,description:`Brennan’s names Creekstone Farms beef tenderloin, roasted and glazed summer squash, and sauce Foyot, serving two. Foyot belongs to the béarnaise family and is enriched with reduced meat glaze.`,image:`A roasted centre-cut tenderloin with three carved slices, summer squash and a separate boat of tan Foyot sauce.`}],links:[{label:`Tenderloin and filet mignon`,href:`/lexicon#tenderloin-filet-mignon`},{label:`Roasting in a hot oven`,href:`/technique/roasting-in-a-hot-oven`}],techniques:[],dishes:[`d-5wcuejdy`],sources:[{title:`Brennan’s: current dinner menu`,url:`https://www.brennansneworleans.com/menus/dinner/`},{title:`Beef Checkoff: Chateaubriand tenderloin roast`,url:`https://www.beefitswhatsfordinner.com/cuts/cut/2446/chateaubriand-tenderloin-roast`}]},{id:`gulf-fish-papillote`,group:`ingredients`,title:`Gulf Fish en Papillote: outside and within`,intro:`Compare the banana-leaf parcel with an opened ingredient study of the same dish.`,scope:`The menu names Gulf fish without specifying its species. The opened view shows the listed ingredients for recognition; it does not establish their proportions, exact cooking sequence, fastening or tableside opening method.`,image:{src:`house/brennans/gulf-fish-papillote-v1.webp`,thumb:`house/brennans/gulf-fish-papillote-v1.thumb.webp`,width:1536,height:1024},subjects:[{name:`A banana-leaf parcel`,description:`En papillote describes cooking inside an enclosure. Although the familiar French version uses paper, this menu specifically names a banana-leaf wrap.`,image:`A folded, closed banana-leaf parcel with no visible string or fastener.`},{name:`The ingredients inside`,description:`The menu lists Gulf fish, Louisiana crab, sorghum, Marcona almonds, Castelvetrano olives and tomato. Compare the round grains, pale almonds and green olives beside the fish and crab.`,image:`An opened banana leaf holding white fish, crab meat, round sorghum grains, pale Marcona almonds, green Castelvetrano olives and tomato.`}],links:[{label:`Steaming and en papillote`,href:`/lexicon#steaming-and-en-papillote`},{label:`Crab vocabulary`,href:`/lexicon#crab-vocabulary`}],techniques:[],dishes:[`d-szzugxzi`],sources:[{title:`Brennan’s: current dinner menu`,url:`https://www.brennansneworleans.com/menus/dinner/`}]},{id:`brennans-seafood`,group:`ingredients`,title:`Seafood on Brennan’s menu`,intro:`Explore six seafood subjects and product forms, from a whole red drum to picked crab meat.`,scope:`These culinary studies are not a wild-species identification key, a catch-origin guarantee or a food-safety test. Whole animals, opened shells and prepared products are shown at different scales. The daily Gulf fish is not necessarily red drum; shrimp curl and illustrated colour do not establish doneness.`,image:{src:`house/brennans/brennans-seafood-v1.webp`,thumb:`house/brennans/brennans-seafood-v1.thumb.webp`,width:1024,height:1536},subjects:[{name:`Red drum, or redfish`,description:`The elongated copper-silver fish and dark spot near the tail are useful visual cues. Keep the named Redfish Véronique distinct from an unspecified Gulf-fish selection.`,image:`A whole copper-silver red drum in side view, with a dark spot near the base of its tail.`},{name:`Eastern oyster`,description:`Compare a rough closed shell with its opened, cupped half. The menu’s Louisiana oysters are a different product from the picked crab meat and peeled shrimp below.`,image:`An irregular closed oyster shell beside an opened cupped half with moist oyster flesh.`},{name:`Crab fingers`,description:`These prepared claw pieces retain a shell tip for handling. Compare that shape with the separate white lumps of picked body meat.`,image:`Cooked crab fingers with exposed pale claw meat and small shell tips.`},{name:`Lump crab meat`,description:`Picked body meat comes in distinct white pieces. Its form differs from claw meat; follow the menu and kitchen specification for the required product.`,image:`A small grouping of ivory-white picked lump crab meat.`},{name:`Crawfish`,description:`The small freshwater crustacean has two prominent claws and a segmented tail. The cooked whole animal helps place the peeled tail meat used in prepared dishes.`,image:`A cooked red crawfish beside two pieces of peeled tail meat.`},{name:`Shrimp`,description:`Compare the segmented tail and slender shrimp form with the clawed crawfish. The illustration shows a cooked product, without proposing a curl-based doneness rule.`,image:`Cooked pink shrimp with clearly segmented bodies.`}],links:[{label:`Oysters: East and West`,href:`/lexicon#oysters-east-vs-west`},{label:`Crab vocabulary`,href:`/lexicon#crab-vocabulary`},{label:`Shrimp sizing`,href:`/lexicon#shrimp-sizing-and-prawn-confusion`}],techniques:[],dishes:[`d-wckf36s5`,`d-5p5b1hjn`,`d-nd0d2czb`,`d-k84u864v`,`d-s1bqzuks`,`d-szzugxzi`,`d-vovhoagi`,`d-bqznncn6`],sources:[{title:`Brennan’s: current dinner menu`,url:`https://www.brennansneworleans.com/menus/dinner/`},{title:`Brennan’s: current breakfast and lunch menu`,url:`https://www.brennansneworleans.com/menus/breakfast-and-lunch/`},{title:`Louisiana Department of Wildlife and Fisheries: red drum`,url:`https://www.wlf.louisiana.gov/species/detail/11`},{title:`NOAA Fisheries: Eastern oyster`,url:`https://www.fisheries.noaa.gov/species/eastern-oyster`},{title:`Louisiana Direct Seafood: crawfish`,url:`https://louisianadirectseafood.com/crawfish/`}]},...e,...i];function c(e){return s.filter(t=>t.techniques.includes(e))}function l(e,t){return e===`h-g02pdomw`?s.filter(e=>e.dishes.includes(t)):[]}function u(e){return`${e.title}. ${e.subjects.length} numbered subjects, read left to right from the top row. ${e.subjects.map((e,t)=>`${t+1}. ${e.name}: ${e.image}`).join(` `)}`}var d={fd_0026:[`braise-confit-render`],fd_0029:[`braise-confit-render`],fd_0047:[`braise-confit-render`],fd_0161:[`brown-butter-study`],fd_0172:[`agnolotti-shaping`],fd_0240:[`meringue-peaks`],fd_0244:[`puff-pastry-layers`],fd_0250:[`custard-structures`],fd_0025:[`simmer-standard`],fd_0034:[`poached-egg-standard`,`simmer-standard`],fd_0036:[`puree-texture-standard`],fd_0039:[`searing-standard`],fd_0040:[`simmer-standard`],fd_0064:[`louisiana-larder`],fd_0077:[`louisiana-larder`],fd_0093:[`chateaubriand-study`],fd_0315:[`chateaubriand-study`],fd_0231:[`gulf-fish-papillote`],fd_0109:[`brennans-seafood`],fd_0115:[`brennans-seafood`],fd_0133:[`brennans-seafood`],fd_0134:[`brennans-seafood`],fd_0196:[`brennans-sauces`],fd_0197:[`brennans-sauces`,`hollandaise-standard`],fd_0205:[`brennans-sauces`]};function f(e){return s.filter(t=>d[e]?.includes(t.id))}function p(e){return s.filter(t=>t.links.some(t=>t.href===`/lexicon#${e}`))}export{l as a,u as c,f as i,s as n,p as o,o as r,c as s,a as t};